// OTA always follows this firmware variant, independently of restored configuration.
const char* getSauluxOtaRelease() {
  switch (SAULUX_MODEL) {
    case 1: return "SAULUX_2I2O";
    case 2: return "SAULUX_5I4O";
    case 3: return "SAULUX_ETHERNET";
    case 4: return "WB_MGU";
    default: return "SAULUX";
  }
}

uint8_t getSauluxPhyAddress() { return phyAddress; }
bool getSauluxStatusInverted() { return statusInverted; }

// Use the STA/base MAC for a stable identity across Wi-Fi and Ethernet profiles.
bool makeSauluxHostname(char* buffer, size_t capacity) {
  if (!buffer || capacity < sizeof("saulux-123456") || escapedMac.length() != 12) return false;
  char suffix[7] = {};
  for (size_t i = 0; i < 12; i++) {
    char c = escapedMac[i];
    if (c >= 'A' && c <= 'F') c += 'a' - 'A';
    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return false;
    if (i >= 6) suffix[i - 6] = c;
  }
  snprintf(buffer, capacity, "saulux-%s", suffix);
  return true;
}

// Recompute network names on every board, including after restoring another board's config.
static bool prepareSauluxIdentity(JsonObject root) {
  char hostname[sizeof("saulux-123456")];
  if (!makeSauluxHostname(hostname, sizeof(hostname))) return false;
  JsonObject id = root["id"].is<JsonObject>() ? root["id"].as<JsonObject>() : root.createNestedObject("id");
  JsonObject ap = root["ap"].is<JsonObject>() ? root["ap"].as<JsonObject>() : root.createNestedObject("ap");
  bool changed = false;
  if (strncmp(id["mdns"] | "", hostname, sizeof(hostname)) != 0) {
    id["mdns"] = hostname;
    changed = true;
  }
  if (strncmp(ap["ssid"] | "", hostname, sizeof(hostname)) != 0) {
    ap["ssid"] = hostname;
    changed = true;
  }
  const char* name = id["name"] | "";
  if (name[0] == '\0' || strncmp(name, "WLED", sizeof("WLED")) == 0
      || (SAULUX_MODEL == 4 && strncmp(name, "WLED_WB_MGE_V3", sizeof("WLED_WB_MGE_V3")) == 0)) {
    id["name"] = SAULUX_MODEL == 4 ? "wb-mgu" : "SAULUX";
    changed = true;
  }
  return changed;
}

// Accept only exact form values; String::toInt() alone also accepts malformed input.
SauluxSettingsResult configureSauluxHardware(const String& address, bool inverted) {
  if (address.length() < 1 || address.length() > 2) return SauluxSettingsResult::Invalid;
  for (size_t i = 0; i < address.length(); i++) if (address[i] < '0' || address[i] > '9') return SauluxSettingsResult::Invalid;
  const int parsedAddress = address.toInt();
  if (parsedAddress > 31) return SauluxSettingsResult::Invalid;
  if (phyAddress == parsedAddress && statusInverted == inverted) return SauluxSettingsResult::Unchanged;
  phyAddress = parsedAddress;
  statusInverted = inverted;
  rebootPending = true;
  return SauluxSettingsResult::Changed;
}

// Wait for the main loop to save hardware options before requesting a reboot.
void handleSauluxReboot() {
  if (rebootPending && !configNeedsWrite) doReboot = true;
}

// Apply this variant on first installation or when replacing another hardware variant.
// This runs before Ethernet, buses, buttons and relay claim any GPIOs.
bool prepareSauluxConfig(JsonObject root) {
  bool needsSave = prepareSauluxIdentity(root);
  // Old menu selections and restored configs cannot change the compiled model.
  needsSave |= (root["saulux"]["model"] | -1) != SAULUX_MODEL;
  const int address = root["saulux"]["phyAddress"] | int(DEFAULT_PHY_ADDRESS);
  phyAddress = address >= 0 && address <= 31 ? address : DEFAULT_PHY_ADDRESS;
  statusInverted = root["saulux"]["statusInverted"] | false;
  const int applied = root["saulux"]["applied"] | -1;
#if SAULUX_MODEL == 4
  reserveWbMguPins();
#endif
  const auto& profile = PROFILES[SAULUX_MODEL - 1];
  if (profile.status >= 0 && PinManager::allocatePin(profile.status, true, PinOwner::StatusLED)) statusPin = profile.status;
  if (applied == SAULUX_MODEL) {
    // Upgrade earlier generated WS2812 outputs once, retaining layout and power limits.
    if ((root["saulux"]["ledDefaults"] | 0) < LED_DEFAULTS_VERSION) {
      for (JsonObject bus : root["hw"]["led"]["ins"].as<JsonArray>()) {
        if ((bus["type"] | TYPE_WS2812_RGB) == TYPE_WS2812_RGB) bus["type"] = TYPE_SK6812_RGBW;
      }
      needsSave = true;
    }
    return needsSave;
  }

  JsonObject hw = root["hw"].is<JsonObject>() ? root["hw"].as<JsonObject>() : root.createNestedObject("hw");
  JsonObject led = hw["led"].is<JsonObject>() ? hw["led"].as<JsonObject>() : hw.createNestedObject("led");
  led.remove("matrix");
  JsonArray buses = led.createNestedArray("ins");
  uint16_t start = 0;
  for (int8_t pin : profile.outputs) {
    if (pin < 0) break;
    JsonObject bus = buses.createNestedObject();
    bus.createNestedArray("pin").add(pin);
    bus["type"] = TYPE_SK6812_RGBW;
    bus["order"] = COL_ORDER_GRB;
    bus["start"] = start;
    bus["len"] = 30;
    start += 30;
  }
  led["total"] = start;
  JsonObject btn = hw.createNestedObject("btn");
  btn["pull"] = true;
  JsonArray inputs = btn.createNestedArray("ins");
  for (int8_t pin : profile.inputs) {
    if (pin < 0) break;
    JsonObject input = inputs.createNestedObject();
    input.createNestedArray("pin").add(pin);
    input["type"] = BTN_TYPE_PUSH;
  }
  JsonObject relay = hw.createNestedObject("relay");
  relay["pin"] = profile.relay;
  relay["rev"] = false;
  relay["odrain"] = false;
  JsonObject interfaces = hw.createNestedObject("if");
  JsonArray i2c = interfaces.createNestedArray("i2c-pin");
  i2c.add(-1); i2c.add(-1);
  JsonArray spi = interfaces.createNestedArray("spi-pin");
  spi.add(-1); spi.add(-1); spi.add(-1);
  root.createNestedObject("eth")["type"] = SAULUX_MODEL >= 3 ? WLED_ETH_ESP32ETHKITVE : WLED_ETH_NONE;
  return true;
}

// Record the fixed profile for subsequent updates and migration from older builds.
void serializeSauluxConfig(JsonObject root) {
  JsonObject config = root.createNestedObject("saulux");
  config["model"] = SAULUX_MODEL;
  config["applied"] = SAULUX_MODEL;
  config["phyAddress"] = phyAddress;
  config["statusInverted"] = statusInverted;
  config["ledDefaults"] = LED_DEFAULTS_VERSION;
}

void setupSauluxStatus() {
  if (statusPin < 0) return;
  digitalWrite(statusPin, statusInverted ? HIGH : LOW);
  pinMode(statusPin, OUTPUT);
}

// Blink faster when connected, slowly in AP mode, and turn off when disconnected.
void handleSauluxStatus() {
#if SAULUX_MODEL == 4
  handleWbMgu();
#endif
  if (statusPin < 0) return;
  const uint32_t interval = Network.isConnected() ? 500 : apActive ? 1000 : 0;
  if (!interval) statusOn = false;
  else if (millis() - statusChanged >= interval) {
    statusChanged = millis();
    statusOn = !statusOn;
  }
  digitalWrite(statusPin, statusOn != statusInverted ? HIGH : LOW);
}
